  - injection H as <-. exists K. rewrite Nat.sub_diag. cbn. auto.
  - destruct (IH (S i) j H) as (K' & Hn & HP' & Hle). exists K'.
    replace (j - i)%nat with (S (j - S i))%nat by lia. cbn [nth_error]. repeat split; try assumption. lia.
Qed.

